        "privacy-1-title": "1. Data Collection",
        "privacy-1-p": "We only collect the information necessary to fulfill your order. For **Elite Cards**, this includes the name and logo you provide for customization. Contact information is only used for delivery purposes within Casablanca and Morocco.",
        "privacy-2-title": "2. NFC Data Security",
        "privacy-2-p": "SuperTap hardware acts as a bridge to your digital profile. We do not store your passwords or private login credentials. The data written to your NFC card or tag is controlled by you via your chosen profile provider.",
        "privacy-3-title": "3. Third-Party Sharing",
        "privacy-3-p": "We do not sell, trade, or rent your personal information to third parties. Your data is strictly used for order processing and customer support.",
        "privacy-4-title": "4. Local Compliance",
        "privacy-4-p": "As a Casablanca-based provider, we respect local privacy standards and strive to ensure your digital networking experience is secure and professional.",
        "privacy-footer": "If you have questions about your data, contact us via WhatsApp or our official TikTok channel.",
        "terms-1-title": "1. Custom Orders",
        "terms-1-p": "For **Elite Edition** cards, customers must provide high-quality logos. Once the customization process begins, orders cannot be canceled or refunded due to the personalized nature of the product.",
        "terms-2-title": "2. Product Use",
        "terms-2-p": "SuperTap cards are designed for contact sharing. We are not responsible for any misuse of the hardware or any third-party profile services linked to the card.",
        "terms-3-title": "3. Delivery Policy",
        "terms-3-p": "Delivery times in Casablanca are typically 24h. We are not liable for external courier delays outside of our direct delivery zone in Morocco.",
        "terms-4-title": "4. Lifetime Warranty",
        "terms-4-p": "We guarantee the internal NFC chip against manufacturing defects. If your chip fails to transmit under normal use, contact us on WhatsApp for a replacement.",
        "terms-footer": "By placing an order with SuperTap, you agree to these Terms of Service.",
