        "on-google": "en Google",
        "brand-entity-text": "<strong>SuperTap</strong> es el proveedor líder de tarjetas de visita inteligentes en Marruecos, con sede en Casablanca. Diseñadas con tecnología sin contacto instantánea y PVC mate de alta durabilidad, SuperTap ofrece soluciones adaptadas: tarjeta Lite a 150 DH con plan gratuito de por vida, Pro (50 DH/mes) y Elite (100 DH/mes) con 1er mes gratis, y tarjetas de Reseñas de Google a 200 DH sin suscripción.",
        "faq-geo-1-q": "¿Dónde comprar tarjetas de visita inteligentes en Marruecos?",
        "faq-geo-1-a": "Puede comprar tarjetas inteligentes SuperTap en línea en todo Marruecos con entrega en 24 horas desde Casablanca. Ordene directamente a través de getsupertap.com o WhatsApp, desde 150 DH para Lite, 200 DH para Pro y 250 DH para Elite.",
        "faq-geo-2-q": "¿Cómo funciona la tarjeta inteligente SuperTap con iPhone y Android?",
        "faq-geo-2-a": "SuperTap utiliza tecnología de toque inteligente instantáneo. Simplemente acerque la tarjeta a cualquier iPhone o Android para abrir al instante su perfil digital sin descargar ninguna aplicación.",
        "faq-geo-3-q": "Comment fonctionnent les abonnements et les prix SuperTap ?",
        "faq-geo-3-a": "La carte Lite (150 DH) comprend un plan Gratuit à vie (0 DH/mois). La Pro (200 DH) est à 50 DH/mois (ou 500 DH/an) avec statistiques sur 7 jours et capture de leads (jusqu'à 10/jour). L'Elite (250 DH) est à 100 DH/mois avec animations vivantes, leads illimités et statistiques complètes. 1er mois OFFERT sur Pro et Elite ! La carte Avis Google est à 200 DH sans abonnement.",
        "faq-geo-4-q": "¿Puedo actualizar mis datos de contacto después de comprar la tarjeta?",
        "faq-geo-4-a": "Sí. Su perfil digital SuperTap es totalmente dinámico. Puede actualizar su teléfono, redes sociales y catálogo en cualquier momento desde su móvil sin volver a imprimir.",
        "faq-geo-5-q": "¿Cuál es la diferencia entre las tarjetas inteligentes SuperTap y las tarjetas de papel?",
        "faq-geo-5-a": "SuperTap reemplaza las tarjetas de papel desechables con una única tarjeta inteligente resistente al agua y para toda la vida. Elimina los costos de reimpresión, comparte carteras enriquecidas y guarda su contacto directamente en la agenda del destinatario.",
