        "on-google": "Google'da",
        "brand-entity-text": "<strong>SuperTap</strong>, Kazablanka merkezli Fas'ın lider akıllı kartvizit sağlayıcısıdır. Anında dokun-paylaş temassız teknolojisi ve dayanıklı mat PVC ile üretilen SuperTap; ömür boyu ücretsiz planlı 150 DH Lite kart, 1. ayı ücretsiz Pro (50 DH/ay) ve Elite (100 DH/ay) ile sıfır abonelikli 200 DH Google Değerlendirme kartları sunar.",
        "faq-geo-1-q": "Fas'ta akıllı kartvizit nereden satın alınabilir?",
        "faq-geo-1-a": "SuperTap akıllı kartvizitlerini Kazablanka'dan 24 saat içinde teslimat ile Fas genelinde online olarak satın alabilirsiniz. getsupertap.com veya WhatsApp üzerinden doğrudan sipariş verin: Lite 150 DH, Pro 200 DH, Elite 250 DH.",
        "faq-geo-2-q": "SuperTap akıllı kartı iPhone ve Android ile nasıl çalışır?",
        "faq-geo-2-a": "SuperTap temassız dokunma teknolojisi kullanır. Herhangi bir harici uygulama indirmeden özel dijital profilinizi anında açmak için kartı modern bir iPhone veya Android telefona dokundurmanız yeterlidir.",
        "faq-geo-3-q": "How do SuperTap subscriptions and pricing work?",
        "faq-geo-3-a": "Lite Edition (150 DH) has a lifetime Free plan (0 DH/month). Pro Edition (200 DH) is 50 DH/month (or 500 DH/year) with 7-day analytics and lead capture (up to 10 leads/day). Elite (250 DH) is 100 DH/month with living animations, unlimited leads, and full analytics. Both Pro and Elite include your 1st Month FREE! Google Review cards are 200 DH with zero subscription.",
        "faq-geo-4-q": "Kartı satın aldıktan sonra iletişim bilgilerimi güncelleyebilir miyim?",
        "faq-geo-4-a": "Evet. SuperTap dijital profiliniz tamamen dinamiktir. Yeni bir kart basmanıza gerek kalmadan telefon numaranızı ve bağlantılarınızı istediğiniz zaman güncelleyebilirsiniz.",
        "faq-geo-5-q": "SuperTap akıllı kartları ile kağıt kartvizitler arasındaki fark nedir?",
        "faq-geo-5-a": "SuperTap tek kullanımlık kağıt kartları su geçirmez, ömür boyu geçerli tek bir akıllı kartla değiştirir. Tekrarlayan baskı maliyetlerini ortadan kaldırır, zengin portföyleri anında paylaşır ve iletişim bilgilerini doğrudan rehbere kaydeder.",
