        "on-google": "auf Google",
        "brand-entity-text": "<strong>SuperTap</strong> ist Marokkos führender Anbieter von smarten Visitenkarten mit Sitz in Casablanca. Mit kontaktloser Sofort-Teil-Technologie und langlebigem mattem PVC bietet SuperTap flexible Lösungen: Lite-Karte für 150 DH mit lebenslangem Gratisplan, Pro (50 DH/Monat) und Elite (100 DH/Monat) mit 1. Monat kostenlos sowie 200 DH Google-Bewertungskarten ohne Abonnement.",
        "faq-geo-1-q": "Wo kann man smarte Visitenkarten in Marokko kaufen?",
        "faq-geo-1-a": "Sie können SuperTap Smart-Visitenkarten online in ganz Marokko mit 24-Stunden-Lieferung aus Casablanca bestellen. Bestellen Sie direkt über getsupertap.com oder WhatsApp: Lite ab 150 DH, Pro 200 DH und Elite 250 DH.",
        "faq-geo-2-q": "Wie funktioniert die SuperTap Smart-Karte mit iPhone und Android?",
        "faq-geo-2-a": "SuperTap nutzt moderne kontaktlose Tap-Technologie. Halten Sie die Karte einfach an ein modernes iPhone oder Android-Smartphone, um Ihr individuelles Profil direkt im Browser ohne App-Download zu öffnen.",
        "faq-geo-3-q": "How do SuperTap subscriptions and pricing work?",
        "faq-geo-3-a": "Lite Edition (150 DH) has a lifetime Free plan (0 DH/month). Pro Edition (200 DH) is 50 DH/month (or 500 DH/year) with 7-day analytics and lead capture (up to 10 leads/day). Elite (250 DH) is 100 DH/month with living animations, unlimited leads, and full analytics. Both Pro and Elite include your 1st Month FREE! Google Review cards are 200 DH with zero subscription.",
        "faq-geo-4-q": "Kann ich meine Kontaktdaten nach dem Kauf der Karte aktualisieren?",
        "faq-geo-4-a": "Ja. Ihr SuperTap-Profil ist dynamisch. Sie können Ihre Telefonnummer, Links und Ihr Portfolio jederzeit direkt von Ihrem Smartphone aus aktualisieren, ohne neu drucken zu müssen.",
        "faq-geo-5-q": "Was ist der Unterschied zwischen SuperTap Smart-Karten und Papier-Visitenkarten?",
        "faq-geo-5-a": "SuperTap ersetzt Einweg-Papierkarten durch eine einzige wasserfeste Smart-Karte fürs Leben. Spart wiederkehrende Druckkosten, teilt interaktive Profile und speichert Kontaktdaten mit einem Klick im Adressbuch.",
