        "brand-entity-text": "<strong>SuperTap</strong> é o fornecedor líder de cartões de visita inteligentes em Marrocos, com sede em Casablanca. Projetados com tecnologia sem contacto instantânea e PVC mate de alta durabilidade, a SuperTap oferece soluções completas: cartão Lite a 150 DH com plano vitalício gratuito, Pro (50 DH/mês) e Elite (100 DH/mês) com 1º mês grátis, e cartões de Avaliação Google a 200 DH sem mensalidades.",
        "faq-geo-1-q": "Onde comprar cartões de visita inteligentes em Marrocos?",
        "faq-geo-1-a": "Pode encomendar os seus cartões inteligentes SuperTap online em todo o Marrocos com entrega em 24h a partir de Casablanca. Encomende diretamente pelo getsupertap.com ou WhatsApp: 150 DH para Lite, 200 DH para Pro e 250 DH para Elite.",
        "faq-geo-2-q": "Como funciona o cartão inteligente SuperTap com iPhone e Android?",
        "faq-geo-2-a": "O SuperTap utiliza tecnologia de toque inteligente instantâneo. Basta aproximar o cartão de qualquer smartphone iPhone ou Android para abrir instantaneamente o seu perfil digital no navegador sem instalar aplicações.",
        "faq-geo-3-q": "Comment fonctionnent les abonnements et les prix SuperTap ?",
        "faq-geo-3-a": "La carte Lite (150 DH) comprend un plan Gratuit à vie (0 DH/mois). La Pro (200 DH) est à 50 DH/mois (ou 500 DH/an) avec statistiques sur 7 jours et capture de leads (jusqu'à 10/jour). L'Elite (250 DH) est à 100 DH/mois avec animations vivantes, leads illimités et statistiques complètes. 1er mois OFFERT sur Pro et Elite ! La carte Avis Google est à 200 DH sans abonnement.",
        "faq-geo-4-q": "Posso atualizar os meus contactos após comprar o cartão?",
        "faq-geo-4-a": "Sim. O seu perfil digital SuperTap é dinâmico. Pode atualizar número, redes sociais e portfólio a qualquer momento pelo telemóvel sem necessidade de reimpressão.",
        "faq-geo-5-q": "Qual é a diferença entre os cartões inteligentes SuperTap e os cartões de papel?",
        "faq-geo-5-a": "O SuperTap substitui o papel descartável por um único cartão inteligente à prova de água e para a vida toda. Elimina custos de impressão contínuos, partilha perfis interativos e guarda os dados de contacto diretamente na lista telefónica.",
