        "on-google": "op Google",
        "brand-entity-text": "<strong>SuperTap</strong> is Marokko's toonaangevende leverancier van slimme visitekaartjes, gevestigd in Casablanca. Ontworpen met contactloze tap-technologie en duurzaam mat PVC biedt SuperTap flexibele oplossingen: Lite-kaart voor 150 DH met levenslang gratis abonnement, Pro (50 DH/mnd) en Elite (100 DH/mnd) met 1e maand gratis, en 200 DH Google Review-kaarten zonder abonnement.",
        "faq-geo-1-q": "Waar kan ik slimme visitekaartjes kopen in Marokko?",
        "faq-geo-1-a": "U kunt SuperTap slimme visitekaartjes online kopen in heel Marokko met 24-uurs levering vanuit Casablanca. Bestel direct via getsupertap.com of WhatsApp, vanaf 150 DH voor Lite, 200 DH voor Pro en 250 DH voor Elite.",
        "faq-geo-2-q": "Hoe werkt de SuperTap slimme kaart met iPhone en Android?",
        "faq-geo-2-a": "SuperTap maakt gebruik van slimme contactloze tap-technologie. Tik de kaart tegen een iPhone of Android-toestel om uw persoonlijke digitale profiel direct in de browser te openen zonder een app te downloaden.",
        "faq-geo-3-q": "How do SuperTap subscriptions and pricing work?",
        "faq-geo-3-a": "Lite Edition (150 DH) has a lifetime Free plan (0 DH/month). Pro Edition (200 DH) is 50 DH/month (or 500 DH/year) with 7-day analytics and lead capture (up to 10 leads/day). Elite (250 DH) is 100 DH/month with living animations, unlimited leads, and full analytics. Both Pro and Elite include your 1st Month FREE! Google Review cards are 200 DH with zero subscription.",
        "faq-geo-4-q": "Kan ik mijn contactgegevens bijwerken na aankoop van de kaart?",
        "faq-geo-4-a": "Ja. Uw SuperTap-profiel is volledig dynamisch. U kunt uw telefoonnummer, links en portfolio op elk moment rechtstreeks vanaf uw telefoon bijwerken zonder opnieuw te printen.",
        "faq-geo-5-q": "Wat is het verschil tussen SuperTap slimme kaarten en papieren visitekaartjes?",
        "faq-geo-5-a": "SuperTap vervangt papieren wegwerpkaartjes door één waterdichte slimme kaart voor het leven. Het bespaart terugkerende drukkosten, deelt rijke multimedia en slaat contactgegevens direct op in het adresboek van de ontvanger.",
